head.script:
scwin.gVar = {
    "cID" : "target1"
}



scwin.onpageload = function () {
    // Global DataList 생성 호출 (dlt_pData 포함)
    $c.gcm.createCommonDatalist();

    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof scwin.target1 !== 'undefined') {
        scwin.target1.remove();;
    }

    // 조건 설정
    let cID = scwin.gVar["cID"];

    // comp 생성
    let grp_comp = $c.gcm.getTestGroup();

    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:pivot ' + strNameSpace + ' dataList="dlt_pData" contextMenuGetter="getContext" style="width:600px;height:600px;margin-top:10px;margin-left:10px;margin-right:10px;" showZero="true" rows="col4,col5,col8" bodyTextAlign="right" totalTextAlign="right" cols="col6,col7" vals="col3" excludeHiddenList="" aggregatorName="Sum" useNumberFormat="true" digitsAfterDecimal="2" showGrandTotal="true" valuesAxis="row" class="mt35" ev:oncellclick="cellClick">';
    strTarget += '<w2:fieldInfo>';
    strTarget += '<w2:field id="col1" name="row" sortOrder="" ></w2:field>';
    strTarget += '<w2:field id="col2" name="total_bill" sortOrder="" ></w2:field>';
    strTarget += '<w2:field id="col3" name="tip" sortOrder="" ></w2:field>';
    strTarget += '<w2:field id="col4" name="sex" sortOrder="" ></w2:field>';
    strTarget += '<w2:field id="col5" name="smoker" sortOrder="" ></w2:field>';
    strTarget += '<w2:field id="col6" name="day" sortOrder="" ></w2:field>';
    strTarget += '<w2:field id="col7" name="time" sortOrder="" ></w2:field>';
    strTarget += '<w2:field id="col8" name="size" sortOrder="" ></w2:field>';
    strTarget += '</w2:fieldInfo>';
    strTarget += '</w2:pivot>';

    scwin.target1 = await $p.dynamicCreate(
        cID,
        "pivot",
        strTarget,
        grp_comp
    );
}
